+
+import org.openjdk.jmc.common.item.IAttribute;
+import org.openjdk.jmc.common.item.IItemCollection;
+import org.openjdk.jmc.common.item.IItemFilter;
+import org.openjdk.jmc.common.item.ItemCollectionToolkit;
+import org.openjdk.jmc.flightrecorder.selection.messages.internal.Messages;
+
+public class ItemBackedSelection extends FlavoredSelectionBase {
+
+	private final IItemCollection selectedItems;
+	private final String directAspectName;
+
+	public ItemBackedSelection(IItemCollection selectedItems, String name) {
+		this(selectedItems, name, null);
+	}
+
+	/**
+	 * Creates a selection with an optional custom display name for its direct-events aspect.
+	 *
+	 * @param selectedItems
+	 *            the retained event collection
+	 * @param name
+	 *            selection name
+	 * @param directAspectName
+	 *            custom aspect label, or null to use the event description
+	 */
+	public ItemBackedSelection(IItemCollection selectedItems, String name, String directAspectName) {
+		super(name);
+		this.selectedItems = Objects.requireNonNull(selectedItems);
+		this.directAspectName = directAspectName;
+	}
+
+	/**
+	 * Returns the items that form the basis of this selection.
+	 * 
+	 * @return the collection of items this selection is based on
+	 */
+	public IItemCollection getItems() {
+		return selectedItems;
+	}
+
+	@Override
+	public Stream<IItemStreamFlavor> getFlavors(
+		IItemFilter filter, IItemCollection items, List<IAttribute<?>> dstAttributes) {
+		boolean itemsApplicableOnPage = ItemCollectionToolkit.filterIfNotNull(selectedItems, filter).hasItems();
+
+		Builder<IItemStreamFlavor> builder = Stream.builder();
+
+		// prio1/2: All selected items, first if they can be shown on the destination page, last otherwise
+		IItemStreamFlavor selectedEventsFlavor = IItemStreamFlavor.build(directAspectName != null ? directAspectName
+				: MessageFormat.format(Messages.getString(Messages.FLAVOR_SELECTED_EVENTS),
+						ItemCollectionToolkit.getDescription(selectedItems)),
+				selectedItems);
+
+		if (itemsApplicableOnPage) {
+			builder.accept(selectedEventsFlavor);
+		}
+
+		// prio2/1: Destination items with properties shared with the selected items
+		IItemCollection dstItems = ItemCollectionToolkit.filterIfNotNull(items, filter);
+		SelectionAspectToolkit.calculatePersistableFilterFlavors(selectedItems, dstItems, items, dstAttributes)
+				.forEach(builder::accept);
+
+		if (!itemsApplicableOnPage) {
+			builder.accept(selectedEventsFlavor);
+		}
+
+		return builder.build();
+	}
+}

